	done := make(chan struct{})
	errCh := make(chan error)

	var osFound types.OS
	for _, d := range diffIDs {
		go func(diffID string) {
			layerInfo, err := ac.analyzeLayer(diffID)
			if err != nil {
				errCh <- xerrors.Errorf("failed to analyze layer: %s : %w", diffID, err)
